const PF_BODY_FALLBACK = BODY_TRANS.en;

function B(lang: string, key: BodyKey): string {
  return BODY_TRANS[lang]?.[key] ?? BODY_TRANS.en?.[key] ?? key;
}

function BL(lang: string, key: BulletKey): string {
  return BULLET_TRANS[lang]?.[key] ?? BULLET_TRANS.en?.[key] ?? key;
}

function S(lang: string, key: SectionKey): string {
  return SECTION_TRANS[lang]?.[key] ?? SECTION_TRANS.en?.[key] ?? key;
}

export function getGameMeta(lang: Lang): Record<string, GameMeta> {
  const L = (META_TRANS as any)[lang] ?? META_TRANS.es;
  const result: Record<string, GameMeta> = {};
  for (const [game, bs] of Object.entries(BGSMAP)) {
    const t = L[game] ?? META_TRANS.es[game as GameKey];
    result[game] = { ...bs, title: t.title ?? game, desc: t.desc, sub: t.sub };
  }
  return result;
}

